const ctx = $input.first().json;
const d = ctx.datosRecolectados || {};

const notas = JSON.stringify({
  tipo_cajon:        d.tipo_cajon,
  proteccion_extra:  d.proteccion_extra,
  correo_contacto:   d.correo_contacto,
  nombre_cliente:    d.nombre_cliente,
  fecha:             d.fecha,
  tipo_flujo:        d.tipo_flujo,
  cotizacion_enviada: ctx.cotizacionEnviada || ctx.cotizadorEnviado,
  escalada_enviada: ctx.clasificacion === 'Consulta' || ctx.escaladaEnviada || false,
  escalada_pendiente: ctx.clasificacion === 'Consulta' ? false : (ctx.escaladaPendiente || false),
  idioma: ctx.idiomaConversacion || null
});

// Estado mapping usando nuevoEstado real del contexto
const estadoValido = ['Nuevo','En calificación','Calificado','Vendedor notificado','Cerrado'];
let estadoFinal;
if (ctx.nuevoEstado && estadoValido.includes(ctx.nuevoEstado)) {
  estadoFinal = ctx.nuevoEstado;
} else if (ctx.esNuevo) {
  estadoFinal = 'Nuevo';
} else {
  estadoFinal = 'En calificación';
}

const fields = {
  Telefono:          '+' + ctx.telefono,
  Nombre_Contacto:   d.nombre_cliente || ctx.nombreContacto || '',
  Articulo:          d.producto || '',
  'Medidas y Peso':  d.medidas || '',
  Estado:            estadoFinal,
  Historial_Mensajes: ctx.nuevoHistorial || '',
  Origen:            'IA de ventas',
  Descripcion_Lead:  ctx.todosRecolectados
    ? `${d.producto || ''} — ${d.medidas || ''}`
    : (d.producto || ''),
  Ultima_Actividad:  new Date().toISOString(),
  Notas:             notas,
};

// Proteccion_extra: guardar como string 'true'/'false' en el campo de Airtable
if (d.proteccion_extra !== null && d.proteccion_extra !== undefined) {
  fields['¿Protección adicional?'] = String(d.proteccion_extra);
}

// Tema_Consulta: solo incluir si hay valor (no sobreescribir con null)
if (ctx.temaConsulta) {
  fields.Tema_Consulta = ctx.temaConsulta;
}

// Clasificacion: Frío/Tibio/Caliente
const clasifMap = { Caliente: 'Caliente', Tibio: 'Tibio', Frio: 'Frío', Frío: 'Frío' };
if (ctx.clasificacion && clasifMap[ctx.clasificacion]) {
  fields.Clasificacion = clasifMap[ctx.clasificacion];
}

// Tipo_Interaccion: Cotización/Consulta/Mixta
const tipoMap = { cotizacion: 'Cotización', consulta: 'Consulta', mixta: 'Mixta' };
if (d.tipo_flujo && tipoMap[d.tipo_flujo]) {
  fields.Tipo_Interaccion = tipoMap[d.tipo_flujo];
}

return [{ json: { ...ctx, _airtableFields: fields } }];

parameters.jsonBody:
={{ JSON.stringify({
  empresa_id: 1,
  phone: '+' + $json.telefono,
  contact_name: $json._airtableFields?.Nombre_Contacto || $json.datosRecolectados?.nombre_cliente || '',
  clasificacion: $json.clasificacion || 'frio',
  datos_calificacion: {
    ...($json.datosRecolectados || {}),
    cotizacion_enviada: !!($json.cotizacionEnviada || $json.cotizadorEnviado),
    escalada_enviada: !!$json.escaladaEnviada,
    idioma: $json.idiomaConversacion || null
  },
  // Solo el mensaje de este turno y la respuesta enviada, completos (20-oct). Antes se armaba
  // partiendo el historial por líneas: se perdían las líneas 2+ de los mensajes largos
  // (estimado, descripción de fotos) y las fotos viejas se reenviaban en cada turno.
  messages: [
    { rol: 'user', contenido: String($json.texto || '').trim() },
    { rol: 'bot', contenido: String($json.mensajeRespuesta || $json.mensaje || '').trim() }
  ].filter(m => m.contenido)
}) }}

